// GET /api/ai?library=palettes|gradients|prompts — the Pro libraries, by entitlement.
//
// Hosted inside api/ai.js (no thirteenth function: tests/unit/account-deletion.test.js
// pins 12). ai.js already holds the Firebase ID-token check and planForUser, and
// already has GET branches (?backlog, ?diag), so this is the least surprising home.
// vercel.json is untouched: its rewrites block is generated by
// scripts/sync-vercel-rewrites.mjs and deep-equal tested, so a hand-added rewrite
// would fail that test; the client calls /api/ai?library=<kind> directly.
//
// Contract:
//   no/invalid token          401, no values
//   signed in, not Pro        403, no values
//   Pro, admin (verified)     200 { kind, total, items } — the whole library in
//                             canonical order, so the client merges nothing
//   always                    Cache-Control: private, no-store; Vary: Authorization
//
// Pro is decided by planForUser from users/{uid}, exactly as the AI tasks do.
// `deps` is injected so the unit test can fake the token and the user document.
// Nothing under src/ is imported here: the function carries only api/ files.

import { planForUser } from '../plans.js'
import { LIBRARY_PALETTES } from './paletteLibrary.js'
import { GALLERY_GRADIENTS } from './gradientGallery.js'
import { COMMUNITY_PROMPTS } from './communityPrompts.js'

export const LIBRARIES = Object.freeze({
  palettes: LIBRARY_PALETTES,
  gradients: GALLERY_GRADIENTS,
  prompts: COMMUNITY_PROMPTS,
})

/**
 * The Pro check, shared by every Pro-only GET this function hosts (the libraries
 * here, the animated icons in ../icons/animated.js). It sends the refusal itself
 * and resolves false, or resolves true for a verified Pro account and the caller
 * sends its own 200. The private, no-store headers go on first, so neither a
 * refusal nor a payload can ever be shared by a cache.
 *
 *   no/invalid token  401      signed in, not Pro  403      plan lookup failed  500
 *
 * @param req   needs headers.authorization
 * @param res   a Vercel/Express-style response
 * @param deps  { verifyIdToken(token, checkRevoked) -> decoded, readUser(uid) -> user doc data }
 */
export async function requireProUser(req, res, { verifyIdToken, readUser }) {
  res.setHeader('Cache-Control', 'private, no-store')
  res.setHeader('Vary', 'Authorization')

  const header = req.headers?.authorization
  if (!header?.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Authentication required' })
    return false
  }

  let decoded
  try {
    // checkRevoked: a disabled or revoked account loses the library at once.
    decoded = await verifyIdToken(header.slice(7), true)
  } catch {
    res.status(401).json({ error: 'Invalid or expired session' })
    return false
  }

  let plan
  try {
    const user = (await readUser(decoded.uid)) || {}
    plan = planForUser({
      subscription: user.subscription || null,
      lifetimeEntitlement: user.lifetimeEntitlement || null,
      // Only a Firebase-verified email may claim an admin entitlement.
      email: decoded.email_verified ? decoded.email : null,
    })
  } catch (err) {
    console.error('library: could not check the plan', { error: err?.message, code: err?.code })
    res.status(500).json({ error: 'Could not check your plan' })
    return false
  }
  if (plan.id !== 'pro') {
    res.status(403).json({ error: 'Pro plan required' })
    return false
  }
  return true
}

/**
 * @param req   needs headers.authorization and query.library
 * @param res   a Vercel/Express-style response
 * @param deps  { verifyIdToken(token, checkRevoked) -> decoded, readUser(uid) -> user doc data }
 */
export async function serveLibrary(req, res, deps) {
  if (!(await requireProUser(req, res, deps))) return

  const kind = req.query?.library
  if (!Object.hasOwn(LIBRARIES, kind)) {
    return res.status(400).json({ error: `Unknown library — expected one of: ${Object.keys(LIBRARIES).join(', ')}` })
  }
  const items = LIBRARIES[kind]
  return res.status(200).json({ kind, total: items.length, items })
}
